<script setup>import{onMounted,ref}from'vue';import{api}from'../../api/http.js';import PageHeader from'../../components/common/PageHeader.vue';import T from'../../components/common/WorkspaceTable.vue';const users=ref([]),roles=ref([]),audit=ref([]),error=ref(''),form=ref({username:'',full_name:'',role_id:'',status:'Active',password:''});async function load(){try{const d=await api.get('/workspace/admin');users.value=d.users;roles.value=d.roles;audit.value=d.audit}catch(x){error.value=x.message}}async function save(){try{await api.post('/workspace/users',form.value);form.value={username:'',full_name:'',role_id:'',status:'Active',password:''};await load()}catch(x){error.value=x.message}}onMounted(load)</script><template><PageHeader title="Administration" description="Manage user access and review audit activity."/><p v-if="error" class="form-error">{{error}}</p><form class="inline-form" @submit.prevent="save"><input v-model="form.username" placeholder="Username" required><input v-model="form.full_name" placeholder="Full name" required><select v-model="form.role_id" required><option value="">Role</option><option v-for="r in roles" :value="r.id">{{r.name}}</option></select><input v-model="form.password" type="password" placeholder="Temporary password" required><button class="primary-button">Create account</button></form><T :columns="[{key:'username',label:'Username'},{key:'full_name',label:'Name'},{key:'role_name',label:'Role'},{key:'status',label:'Status'},{key:'last_login',label:'Last login'}]" :rows="users"/><h2 class="section-title">Recent audit log</h2><T :columns="[{key:'created_at',label:'Date'},{key:'username',label:'User'},{key:'action',label:'Action'},{key:'entity_type',label:'Entity'}]" :rows="audit"/></template>